style.css:
@keyframes hippie {
    0% { background-position: 0 0; }
    50% { background-position: 0 -100px; }
}
@-moz-document regexp("(?!http://www\.discord\.com).*") {
/*
		the code in here applies to all URLs except those that start with 
		http://www.discord.com
	*/
}

@-moz-document domain("images.discord.com"), url-prefix("http://discord.com/channels") {
/* 
		the code in here only applies to:
			-pages on the domain images.discord.com
			-pages whose URLs start with http://discord.com/channels
	*/
}
